import { writeFile } from "node:fs/promises";
import { stringify } from "yaml";
import { specifications, specificationFiles } from "../dist/specifications.js";

for (const kind of Object.keys(specifications)) {
  await writeFile(
    new URL(`../../../docs/${specificationFiles[kind]}`, import.meta.url),
    "# Generated by silvermoon generate-specs; edit src/checkpoints/ and src/specifications.ts.\n" +
      stringify(specifications[kind], { blockQuote: "literal", lineWidth: 0 }),
  );
}
